import {FxFactors} from './fx-model.js?v=1000';
import {EventDirector} from './events.js?v=1000';
import {INSTRUMENTS,QUOTE_KEYS} from './instruments.js?v=1000';
import {newGame,gameResult} from './gameplay.js?v=1000';
import {executionCost} from './execution.js?v=1000';
import {Market} from './market.js?v=1000';
import {loanBook,accrue,debt,createLoan,creditPayment} from './loans.js?v=1000';
import {emptyStats,statsFromLogs,recordExit,report} from './settlement.js?v=1000';
// All quantities are units of each instrument base currency; all money/P&L is JPY.
export const RULES={initial:1000000,marginRate:.04,liquidationRatio:1,minUnits:1000,maxUnits:150000,maxExposure:25000000,swapLong:-18,swapShort:12};
const money=x=>Math.round((x+Number.EPSILON)*100)/100;
export class Engine {
 constructor(seed=3093,round=1){this.round=round;this.bold=false;this.seed=seed>>>0||1;this.rng=this.seed;this.market=new Market(this.seed,round);this.balance=RULES.initial;this.stats=emptyStats();this.loans=loanBook();this.settlement=null;this.positions=[];this.orders=[];this.logs=[];this.nextId=1;this.time=Date.UTC(2026,9,12,0);this.mid=150;this.spread=.003;this.bid=149.9985;this.ask=150.0015;this.vol=.018;this.depth=180000;this.tick=0;this.lastSwapDay='';this.history=[this.point()];this.curve=[{time:this.time,equity:this.balance}];this.peak=this.balance;this.maxDrawdown=0;this.halted=false;this.pair='USDJPY';this.instruments={};this.game=newGame(this.seed);this.market.pair='USDJPY';this.eventDirector=new EventDirector(this.seed);this.fxFactors=new FxFactors(this.seed);this.initInstruments();this.log('账户创建','初始虚拟资金 ¥1,000,000');}
 initInstruments(){for(const [pair,c]of Object.entries(INSTRUMENTS)){if(pair===this.pair||this.instruments[pair])continue;const m=new Market((this.seed^Math.imul(Object.keys(INSTRUMENTS).indexOf(pair)+1,0x85ebca6b))>>>0,this.round);m.pair=pair;m.extreme=null;m.base=c.start;m.scale=c.scale;m.spreadScale=c.spread;m.fair=m.fundamental=c.start;this.instruments[pair]={mid:c.start,bid:c.start-.003*c.spread/2,ask:c.start+.003*c.spread/2,spread:.003*c.spread,vol:.018*c.scale,depth:180000,market:m,history:[{time:this.time,mid:c.start,bid:c.start-.003*c.spread/2,ask:c.start+.003*c.spread/2}]};}}
 instrument(pair=this.pair){if(!INSTRUMENTS[pair])throw Error('未知货币对');return pair===this.pair?this:this.instruments[pair];}
 setInstrument(pair){if(!INSTRUMENTS[pair])throw Error('未知货币对');if(pair===this.pair)return;this.instruments[this.pair]=Object.fromEntries(QUOTE_KEYS.map(k=>[k,this[k]]));const q=this.instruments[pair];for(const k of QUOTE_KEYS)this[k]=q[k];this.pair=pair;}
 setGameMode(mode){this.requireActive();if(this.tick||this.stats.entries||this.orders.length||this.game.startedAt!=null)throw Error('请在开局推进或下单前选择局制');if(!['free','sprint','sprint20'].includes(mode))throw Error('局制无效');this.game.mode=mode==='sprint'?'sprint20':mode;const x=this.instrument('USDJPY').market.extreme;if(x&&!x.fired){x.baseAt??=x.at;x.at=this.isRealtime()?180+(x.baseAt-20)*6:x.baseAt;}}
 isRealtime(){return this.game.mode==='sprint20';}
 beginRealtime(now=Date.now()){if(this.isRealtime()&&!this.settlement&&this.game.startedAt==null){this.game.startedAt=now;this.game.deadline=now+1200000;this.game.finishedAt=null;}}
 updateRealtime(now=Date.now()){if(this.isRealtime()&&this.game.deadline!=null&&!this.settlement&&now>=this.game.deadline){this.expiring=true;this.game.finishedAt=this.game.deadline;this.game.endReason='现实20分钟到时';try{this.settle();}finally{this.expiring=false;}return true;}return false;}
 skipClosed(){this.requireActive();if(this.isOpen())throw Error(this.isRealtime()?'20分钟模式全天连续交易，无需跳过休市':'当前已经开市');let skipped=0;while(!this.isOpen()&&!this.settlement&&!this.halted&&skipped<10080){this.step();skipped++;}this.log('跳过休市',`已推进 ${skipped} 个模拟分钟；挂单有效期与借款仍照常检查`);return skipped;}
  rules(){if(this.isRealtime())return {...RULES,marginRate:0,liquidationRatio:0,maxUnits:1000000,maxExposure:Infinity,oneClickLeverage:10};return this.bold?{...RULES,marginRate:.025,liquidationRatio:.75,maxUnits:500000,maxExposure:200000000}:RULES;}
 setBold(value){this.requireActive();if(this.isRealtime())throw Error('现实20分钟模式已使用独立的免保证金规则');if(this.positions.length||this.orders.length)throw Error('请先平仓并撤单再切换模式');if(this.halted)throw Error('本局已结束');this.bold=!!value;}
 canBorrow(){const a=this.account();if(this.isRealtime())return !this.settlement&&!this.halted&&this.positions.length>0&&a.equity>0&&a.equity-this.debt()<=350000;return !this.settlement&&!this.halted&&a.margin>0&&a.equity>0&&a.ratio<=this.rules().liquidationRatio*1.5;}
 allIn(side){this.requireActive();if(!this.bold&&!this.isRealtime())throw Error('请先开启梭哈挑战模式');if(this.isRealtime()){const units=Math.min(this.rules().maxUnits,Math.floor(Math.max(0,this.account().equity)*10/this.mid/1000)*1000);if(units<1000)throw Error('净值不足以建立参考仓位');return this.place({side,units,type:'market'});}this.validate({side,units:1000});const a=this.account(),r=this.rules();const budget=Math.max(0,a.free)*.85;let units=Math.min(r.maxUnits,Math.floor(Math.max(0,r.maxExposure-a.exposure)/this.mid/1000)*1000,Math.floor(budget/(this.mid*r.marginRate+this.spread)/1000)*1000);
 // A bounded normal draw reserves execution costs; never retry or reroll a rejected fill.
 while(units>=1000&&units*(this.mid*r.marginRate+this.spread+executionCost(units,this.vol,this.depth,this.spread,this.market.lastJump).reserve)>budget)units-=1000;
 if(units<1000)throw Error('可交易资金不足最小单位');return this.place({side,units,type:'market'});}
 random(){let x=this.rng;x^=x<<13;x^=x>>>17;x^=x<<5;this.rng=x>>>0;return (this.rng+.5)/4294967296;}
 normal(){return Math.sqrt(-2*Math.log(this.random()))*Math.cos(2*Math.PI*this.random());}
 point(){return {time:this.time,mid:this.mid,bid:this.bid,ask:this.ask};}
 log(type,message,extra={}){this.logs.unshift({id:this.nextId++,time:this.time,type,message,...extra});if(this.logs.length>3000)this.logs.pop();}
 isOpen(){if(this.isRealtime())return true;const d=new Date(this.time);const day=d.getUTCDay(),h=d.getUTCHours();return !(day===6||day===0&&h<21||day===5&&h>=21);}
 pnl(p){const q=this.instrument(p.pair??'USDJPY');return money((p.side==='buy'?q.bid-p.entry:p.entry-q.ask)*p.units);}
 account(){const floating=money(this.positions.reduce((s,p)=>s+this.pnl(p),0));const equity=money(this.balance+floating);const exposure=this.positions.reduce((s,p)=>s+p.units*this.instrument(p.pair??'USDJPY').mid,0);const margin=this.isRealtime()?0:money(this.positions.reduce((sum,p)=>sum+p.units*this.instrument(p.pair??'USDJPY').mid*(p.marginRate??this.rules().marginRate),0));return {balance:this.balance,floating,equity,exposure,margin,free:money(equity-margin),ratio:margin?equity/margin:Infinity,leverage:equity>0?exposure/equity:0};}
 quote(side,units,market=true,pair=this.pair){const q=this.instrument(pair),base=side==='buy'?q.ask:q.bid;const cost=executionCost(units,q.vol,q.depth,q.spread,q.market.lastJump);const slip=market?cost.impact+Math.abs(this.normal())*cost.uncertainty:0;return {price:Number((base+(side==='buy'?slip:-slip)).toFixed(5)),slip};}
 validate({side,units,type='market',price,sl,tp,trail,expiry,pair=this.pair}){this.requireActive();const q=this.instrument(pair);if(this.halted)throw Error('账户已资不抵债，请重开一局');if(!this.isOpen())throw Error('市场休市，等待周日纽约时段重新开市');if(!['buy','sell'].includes(side))throw Error('买卖方向无效');if(!Number.isFinite(units)||units<RULES.minUnits||units>this.rules().maxUnits||units%1000)throw Error('数量需为 1,000 的整数倍，单笔超过当前模式上限');if(!['market','limit','stop'].includes(type))throw Error('订单类型无效');if(type!=='market'&&(!Number.isFinite(price)||price<=0))throw Error('请输入有效挂单价格');if(trail!=null&&(!Number.isFinite(trail)||trail<.01||trail>10))throw Error('移动止损距离须在 1–1,000 pips 之间');if(expiry!=null&&(!Number.isFinite(expiry)||expiry<=this.time))throw Error('挂单有效期必须晚于当前时间');const ref=type==='market'?(side==='buy'?q.ask:q.bid):price;for(const [key,val]of [['sl',sl],['tp',tp]]){if(val!=null&&(!Number.isFinite(val)||val<=0))throw Error('止损/止盈价格无效');if(val!=null&&((side==='buy'&&key==='sl'||side==='sell'&&key==='tp')?val>=ref:val<=ref))throw Error('止损或止盈方向与建仓价格不符');}if(type==='limit'&&(side==='buy'?price>=q.ask:price<=q.bid))throw Error('限价单应在当前买价下方 / 卖价上方');if(type==='stop'&&(side==='buy'?price<=q.ask:price>=q.bid))throw Error('突破单应在当前买价上方 / 卖价下方');}
 place(input){const o={type:'market',pair:this.pair,...input};this.validate(o);if(o.type==='market')return this.open(o);if(this.orders.length>=50)throw Error('挂单数量上限为 50');this.beginRealtime();o.id=this.nextId++;o.created=this.time;this.orders.push(o);this.log('挂单',`${o.side==='buy'?'买入':'卖出'} ${o.units.toLocaleString()} ${INSTRUMENTS[o.pair].base} (${o.pair}) · ${o.type==='limit'?'限价':'突破'} ${o.price.toFixed(3)}`,{orderId:o.id});return o;}
 placeOCO({units,upper,lower,trail,expiry}){if(this.orders.length>48)throw Error('挂单数量上限为 50');const buy={pair:this.pair,type:'stop',side:'buy',units,price:upper,trail,expiry},sell={pair:this.pair,type:'stop',side:'sell',units,price:lower,trail,expiry};this.validate(buy);this.validate(sell);const group=this.nextId++;const a=this.place({...buy,group}),b=this.place({...sell,group});this.log('OCO组合',`突破买 ${upper.toFixed(3)} / 突破卖 ${lower.toFixed(3)}，一侧成交即撤另一侧`);return[a,b];}
 editOrder(id,changes){this.requireActive();const o=this.orders.find(x=>x.id===id);if(!o)throw Error('挂单已不存在');if(o.group)throw Error('OCO组合请撤销后重新提交');const next={...o,...changes};this.validate(next);Object.assign(o,next);this.log('修改挂单',`#${id} · 新触发价 ${o.price.toFixed(3)}`);}
 open(o){this.requireActive();const pair=o.pair??this.pair,market=this.instrument(pair),q=this.quote(o.side,o.units,o.type!=='limit',pair);if(o.type==='limit')q.price=o.side==='buy'?Math.min(q.price,o.price):Math.max(q.price,o.price);const a=this.account(),mark=o.side==='buy'?market.bid:market.ask;const immediate=(o.side==='buy'?mark-q.price:q.price-mark)*o.units;const total=a.exposure+o.units*market.mid;const margin=a.margin+o.units*market.mid*this.rules().marginRate;if(a.equity+immediate<=0||!this.isRealtime()&&(total>this.rules().maxExposure||a.equity+immediate<margin))throw Error(this.isRealtime()?'成交成本将耗尽净资金，请减少数量':'成交后净值不足以覆盖当前保证金，或超过持仓上限');const p={pair,id:this.nextId++,side:o.side,units:o.units,entry:q.price,sl:o.sl??null,tp:o.tp??null,trail:o.trail??null,anchor:mark,created:this.time,swap:0,marginRate:this.rules().marginRate};this.beginRealtime();this.positions.push(p);this.stats.entries++;if(p.sl!=null||p.trail!=null)this.game.protectedEntries++;if(p.trail!=null)this.updateTrail(p);this.log('建仓',`${p.side==='buy'?'买入':'卖出'} ${p.units.toLocaleString()} ${INSTRUMENTS[pair].base} (${pair}) @ ${p.entry.toFixed(5)}`,{positionId:p.id,price:q.price,slippage:q.slip});this.trackEquity();return p;}
 cancel(id){this.requireActive();const o=this.orders.find(x=>x.id===id);if(!o)throw Error('挂单已不存在');this.orders=this.orders.filter(x=>o.group?x.group!==o.group:x.id!==id);this.log('撤单',o.group?`撤销 OCO 组合 #${o.group}`:`撤销挂单 #${id}`);}
 updateTrail(p){if(p.trail==null)return;const q=this.instrument(p.pair??'USDJPY'),mark=p.side==='buy'?q.bid:q.ask;p.anchor=p.side==='buy'?Math.max(p.anchor??mark,mark):Math.min(p.anchor??mark,mark);const candidate=Number((p.anchor+(p.side==='buy'?-p.trail:p.trail)).toFixed(5));p.sl=p.sl==null?candidate:p.side==='buy'?Math.max(p.sl,candidate):Math.min(p.sl,candidate);}
 setTrail(id,distance){this.requireActive();const p=this.positions.find(x=>x.id===id);if(!p)throw Error('持仓已不存在');if(distance!=null&&(!Number.isFinite(distance)||distance<.01||distance>10))throw Error('移动止损距离须在 1–1,000 pips 之间');p.trail=distance;const q=this.instrument(p.pair??'USDJPY');p.anchor=p.side==='buy'?q.bid:q.ask;this.updateTrail(p);this.log('移动止损',`#${id} · ${distance==null?'已关闭，保留当前止损价':(distance/.01).toFixed(1)+' pips'}`);}
 modify(id,sl,tp){this.requireActive();const p=this.positions.find(x=>x.id===id);if(!p)throw Error('持仓已不存在');const q=this.instrument(p.pair??'USDJPY'),ref=p.side==='buy'?q.bid:q.ask;for(const [k,v]of [['sl',sl],['tp',tp]])if(v!=null&&(!Number.isFinite(v)||v<=0||((p.side==='buy'&&k==='sl'||p.side==='sell'&&k==='tp')?v>=ref:v<=ref)))throw Error('新止损/止盈须位于当前平仓报价的正确一侧');p.sl=sl;p.tp=tp;this.log('改单',`持仓 #${id} · 止损 ${sl??'无'} / 止盈 ${tp??'无'}`);}
 close(id,units,reason='手动平仓'){this.requireActive();if(!this.isOpen()&&!this.settling)throw Error('市场休市，无法平仓');const p=this.positions.find(x=>x.id===id);if(!p)throw Error('持仓已不存在');units=units??p.units;if(!Number.isFinite(units)||units<=0||units>p.units||units%1000)throw Error('平仓数量无效');const q=this.settling&&!this.isOpen()?{price:p.side==='buy'?this.instrument(p.pair??'USDJPY').bid:this.instrument(p.pair??'USDJPY').ask,slip:0}:this.quote(p.side==='buy'?'sell':'buy',units,reason!=='止盈',p.pair??'USDJPY');if(reason==='止盈')q.price=p.side==='buy'?Math.max(q.price,p.tp):Math.min(q.price,p.tp);const pnl=money((p.side==='buy'?q.price-p.entry:p.entry-q.price)*units);this.balance=money(this.balance+pnl);recordExit(this.stats,pnl,units);p.units-=units;if(p.units===0)this.positions=this.positions.filter(x=>x.id!==id);this.log(reason,`${units.toLocaleString()} ${INSTRUMENTS[p.pair??'USDJPY'].base} (${p.pair??'USDJPY'}) @ ${q.price.toFixed(5)} · ${pnl>=0?'+':''}¥${pnl.toFixed(2)}`,{positionId:id,pnl,price:q.price,slippage:q.slip});this.trackEquity();this.risk();return pnl;}
 risk(){if(this.liquidating)return;const a=this.account();if(!this.isRealtime()&&a.margin&&a.ratio<this.rules().liquidationRatio&&this.isOpen()){this.liquidating=true;this.orders=[];this.stats.forced++;this.log('强制平仓',`保证金维持率低于 ${this.rules().liquidationRatio*100}%，取消挂单并依次平掉全部仓位`);for(const p of [...this.positions].sort((x,y)=>this.pnl(x)-this.pnl(y)))this.close(p.id,p.units,'强平成交');this.liquidating=false;}if(this.account().equity<=0){this.halted=true;this.orders=[];if(this.isRealtime()&&!this.settling&&!this.settlement){this.game.endReason='净资金耗尽';this.settle();}}}
 process(){if(this.settlement||!this.isOpen())return;this.risk();for(const p of [...this.positions]){if(!this.positions.includes(p))continue;this.updateTrail(p);const q=this.instrument(p.pair??'USDJPY'),mark=p.side==='buy'?q.bid:q.ask;if(p.sl!=null&&(p.side==='buy'?mark<=p.sl:mark>=p.sl))this.close(p.id,p.units,'止损');else if(p.tp!=null&&(p.side==='buy'?mark>=p.tp:mark<=p.tp))this.close(p.id,p.units,'止盈');}for(const o of [...this.orders]){if(!this.orders.includes(o))continue;const q=this.instrument(o.pair??'USDJPY'),mark=o.side==='buy'?q.ask:q.bid;const hit=o.type==='limit'?(o.side==='buy'?mark<=o.price:mark>=o.price):(o.side==='buy'?mark>=o.price:mark<=o.price);if(hit){this.orders=this.orders.filter(x=>x.id!==o.id);try{this.open(o);if(o.group){this.orders=this.orders.filter(x=>x.group!==o.group);this.log('OCO联动撤单',`组合 #${o.group} 已成交，撤销另一侧`);}}catch(e){this.log('订单拒绝',`挂单 #${o.id}: ${e.message}`);}}}this.risk();}
 step(){this.updateRealtime();if(this.settlement||this.halted)return this.account();this.stepping=true;try{const wasOpen=this.isOpen();this.time+=60000;this.tick++;for(const o of [...this.orders])if(this.orders.includes(o)&&o.expiry!=null&&o.expiry<=this.time){this.orders=this.orders.filter(x=>o.group?x.group!==o.group:x.id!==o.id);this.log('挂单到期',`#${o.id} 已到期撤销`);}if(this.isOpen()){const frame=this.fxFactors.advance(this.time);for(const pair of Object.keys(INSTRUMENTS))this.instrument(pair).market.lastMid=this.instrument(pair).mid;this.eventDirector.advance(this.time,Object.keys(INSTRUMENTS).map(pair=>this.instrument(pair)));for(const pair of Object.keys(INSTRUMENTS)){const v=this.instrument(pair),q=v.market.advance(this.time,v.mid,!wasOpen,false,frame);v.mid=q.mid;v.spread=q.spread;v.vol=q.vol;v.depth=q.depth;v.bid=Number((v.mid-v.spread/2).toFixed(5));v.ask=Number((v.mid+v.spread/2).toFixed(5));}this.rollover();this.process();}accrue(this.loans,this.time);this.collectInstallment();for(const pair of Object.keys(INSTRUMENTS)){const q=this.instrument(pair);q.history.push({time:this.time,mid:q.mid,bid:q.bid,ask:q.ask});if(q.history.length>50000)q.history.shift();}const a=this.account();const wealth=a.equity-this.debt();this.game.peakLeverage=Math.max(this.game.peakLeverage,a.leverage);this.peak=Math.max(this.peak,wealth);this.maxDrawdown=Math.max(this.maxDrawdown,(this.peak-wealth)/this.peak);this.curve.push({time:this.time,equity:wealth});if(this.curve.length>50000)this.curve.shift();this.game.peakLeverage=Math.max(this.game.peakLeverage,a.leverage);}finally{this.stepping=false;}this.updateRealtime();return this.account();}
 rollover(){const d=new Date(this.time),day=d.toISOString().slice(0,10);if(d.getUTCHours()!==22||d.getUTCMinutes()!==0||day===this.lastSwapDay)return;this.lastSwapDay=day;const multiplier=d.getUTCDay()===3?3:1;for(const p of this.positions){const value=money((p.side==='buy'?INSTRUMENTS[p.pair??'USDJPY'].swapLong:INSTRUMENTS[p.pair??'USDJPY'].swapShort)*p.units/1000*multiplier);p.swap=money(p.swap+value);this.stats.swap=money(this.stats.swap+value);this.balance=money(this.balance+value);this.log('隔夜结算',`持仓 #${p.id} · ${multiplier}日 · ${value>=0?'+':''}¥${value}`,{positionId:p.id,swap:value});}}
 requireActive(){if(!this.stepping&&!this.expiring&&!this.settling&&!this.liquidating)this.updateRealtime();if(this.settlement)throw Error('本轮已结算，请重新开始游戏');}
 trackEquity(){const a=this.account();const wealth=a.equity-this.debt();this.game.peakLeverage=Math.max(this.game.peakLeverage,a.leverage);this.peak=Math.max(this.peak,wealth);this.maxDrawdown=Math.max(this.maxDrawdown,(this.peak-wealth)/this.peak);}
 settle(){if(this.settlement)return this.settlement;if(this.isRealtime()&&!this.expiring&&!this.settling&&this.game.deadline!=null&&Date.now()>=this.game.deadline){this.updateRealtime();return this.settlement;}if(this.isRealtime())this.game.finishedAt??=Date.now();this.orders=[];this.settling=true;this.liquidating=true;try{for(const p of [...this.positions])this.close(p.id,p.units,this.isOpen()?'本轮结算平仓':'休市估值结算');}finally{this.settling=false;this.liquidating=false;}const owed=this.debt();if(owed){accrue(this.loans,this.time);const shortage=this.balance<owed;const paid=money(Math.min(owed,Math.max(0,this.balance)));if(paid>0){this.balance=money(this.balance-paid);creditPayment(this.loans,paid,this.time);}if(shortage&&!this.loans.default)this.loans.default={time:this.time,required:owed,reason:'结算资金不足以清偿借款'};}this.trackEquity();this.settlement=report(this);this.settlement.final=money(this.balance-this.debt());this.settlement.net=money(this.settlement.final-RULES.initial);this.settlement.returnPct=this.settlement.net/RULES.initial*100;this.settlement.unpaidDebt=this.debt();this.settlement.loanBorrowed=this.loans.borrowed;this.settlement.loanRepaid=this.loans.repaid;this.settlement.loanInterest=money(this.loans.interestPaid+(this.loans.active?.interest??0));this.settlement.loanDefault=this.loans.default;this.settlement.game=gameResult(this);this.settlement.realMinutes=this.game.startedAt==null?0:Math.max(0,(this.game.finishedAt-this.game.startedAt)/60000);this.settlement.roundMode=this.game.mode;this.settlement.endReason=this.game.endReason??'主动结算';this.log('本轮结算',`最终资金 ¥${this.balance.toFixed(2)}，净收益 ¥${this.settlement.net.toFixed(2)}`);this.curve.push({time:this.time,equity:this.balance-this.debt()});return this.settlement;}
 debt(){return debt(this.loans,this.time);}
 borrow(amount,plan){this.requireActive();if(this.halted)throw Error('本局已结束');if(!this.canBorrow())throw Error(this.isRealtime()?'仅有持仓、扣债净资金不高于35万日元且账户净值为正时可借救急资金':`仅持仓维持率不高于${this.rules().liquidationRatio*150}%且尚未穿仓时可借救急资金`);const l=createLoan(this.loans,amount,plan,this.time);if(this.isRealtime()){l.period*=10;l.nextDue=this.time+l.period*60000;}this.balance=money(this.balance+amount);this.log('借款到账',`¥${amount} · 每${l.period}分钟复利${(l.rate*100).toFixed(0)}% · 3期`);return l;}
 repay(amount){this.requireActive();const owed=this.debt();if(!owed)throw Error('当前没有借款');amount=money(amount??owed);const cash=Math.min(this.balance,Math.max(0,this.account().free));if(amount>cash+.005)throw Error('可用现金不足，请先减仓或平仓释放保证金');const paid=creditPayment(this.loans,amount,this.time);this.balance=money(this.balance-paid);this.log('借款还款',`偿还 ¥${paid.toFixed(2)}，剩余 ¥${this.debt().toFixed(2)}`);this.trackEquity();return paid;}
 collectInstallment(){const l=this.loans.active;if(!l||this.settlement||this.time<l.nextDue)return;const required=money(l.paidTerms===l.terms-1?this.debt():Math.min(l.installment,this.debt()));const cash=Math.min(this.balance,Math.max(0,this.account().free));if(cash+.005<required){this.loans.default={time:this.time,required,available:Math.max(0,cash),reason:'到期未能支付应还金额'};this.log('借款违约',`到期应还 ¥${required}，可用现金不足，本局结束`);this.settle();return;}this.repay(required);if(this.loans.active){l.paidTerms++;l.nextDue+=l.period*60000;}}
 snapshot(){return JSON.parse(JSON.stringify(this));}
 static restore(data){if(!data||![1,2].includes(data.version)||!data.engine||!Number.isFinite(data.engine.balance)||!Array.isArray(data.engine.positions)||!Number.isFinite(data.engine.rng))throw Error('存档格式不兼容');data=JSON.parse(JSON.stringify(data));const e=new Engine();Object.assign(e,data.engine);e.market=Market.restore(data.engine.market,e.seed);if(!data.engine.market)e.market.fair=e.mid;e.stats=data.engine.stats??statsFromLogs(e.logs);e.loans=data.engine.loans??loanBook();for(const p of e.positions)p.marginRate??=data.engine.bold?.01:.04;e.round=data.engine.round??1;e.bold=data.engine.bold??false;e.pair=data.engine.pair??'USDJPY';e.instruments=data.engine.instruments??{};e.game={...newGame(e.seed),...data.engine.game};if(e.game.mode==='sprint')e.game.mode='sprint20';e.game.duration=20;e.game.durationMs=1200000;for(const p of [...e.positions,...e.orders])p.pair??='USDJPY';for(const [pair,q]of Object.entries(e.instruments))q.market=Market.restore(q.market,e.seed);e.market.pair=e.pair;for(const [pair,q]of Object.entries(e.instruments))q.market.pair=pair;e.eventDirector=EventDirector.restore(data.engine.eventDirector,e.seed);e.fxFactors=FxFactors.restore(data.engine.fxFactors,e.seed);e.initInstruments();e.settling=false;e.liquidating=false;return e;}
}

